    const authorText = findNodes(frame, n => n.type === "TEXT" && n.characters === "Andrew Johnson")[0];
    if (authorText) {
      authorText.reactions = [{
        trigger: { type: "ON_CLICK" },
        actions: [{ type: "NODE", destinationId: authorId, navigation: "NAVIGATE", transition: null }]
      }];
      report[frame.name].specials.push("Andrew Johnson");
    }
  }

  if (frame.name === "05_Category_Business") {
    const breadcrumb = findNodes(frame, n => n.name === "Breadcrumb" || (n.type === "TEXT" && n.characters.includes("BLOG > BUSINESS")))[0];
    if (breadcrumb) {
      breadcrumb.reactions = [{
        trigger: { type: "ON_CLICK" },
        actions: [{ type: "NODE", destinationId: blogId, navigation: "NAVIGATE", transition: null }]
      }];
      report[frame.name].specials.push("Breadcrumb");
    }
  }
}

return { success: true, report: report };

// Let's verify that figma.currentPage is the Workspace page so that we don't have any issues.
const workspacePage = figma.root.children.find(c => c.name.includes("Workspace") || c.id === "3:2");
await figma.setCurrentPageAsync(workspacePage);

return {
  success: true,
  currentPageId: figma.currentPage.id,
  currentPageName: figma.currentPage.name
};
